"use client";
import { usePremiumUpgrade } from "@/components/premium-upgrade-provider";

import {
  useEffect,
  useId,
  useRef,
  useState,
  useSyncExternalStore,
} from "react";
import Link from "next/link";
import { Tooltip } from "@/components/ui/Tooltip";
import { useWorkspaceEntitlements } from "@/components/workspace-quota";
import { Check, Crown } from "lucide-react";

const highlightColors = [
  "Cyan",
  "Teal",
  "Emerald",
  "Lime",
  "Amber",
  "Orange",
  "Rose",
  "Pink",
  "Violet",
  "Blue",
] as const;
type HighlightColor = Lowercase<(typeof highlightColors)[number]>;
const storageKey = "mailloop-preview-highlight";
const listeners = new Set<() => void>();
let current: HighlightColor = "cyan";
let initialized = false;
function validated(value: string | null): HighlightColor {
  return highlightColors.some((name) => name.toLowerCase() === value)
    ? (value as HighlightColor)
    : "cyan";
}
function notify() {
  listeners.forEach((listener) => listener());
}
function subscribe(listener: () => void) {
  listeners.add(listener);
  if (!initialized) {
    initialized = true;
    try {
      current = validated(localStorage.getItem(storageKey));
    } catch {
      /* Storage is optional. */
    }
    notify();
  }
  const sync = (event: StorageEvent) => {
    if (event.key === storageKey || event.key === null) {
      current = validated(event.newValue);
      notify();
    }
  };
  window.addEventListener("storage", sync);
  return () => {
    listeners.delete(listener);
    window.removeEventListener("storage", sync);
  };
}
export function usePreviewHighlight() {
  const access = useWorkspaceEntitlements();
  const preference = useSyncExternalStore(
    subscribe,
    () => current,
    () => "cyan" as HighlightColor,
  );
  return access.features.previewHighlightColors ? preference : "cyan";
}
function choose(color: HighlightColor) {
  current = color;
  try {
    localStorage.setItem(storageKey, color);
  } catch {
    /* Keep the in-memory preference. */
  }
  notify();
}

export function PreviewHighlightPicker() {
  const access = useWorkspaceEntitlements();
  return (
    <ColorPicker
      key={String(access.features.previewHighlightColors)}
      premium={access.features.previewHighlightColors}
    />
  );
}

function ColorPicker({ premium }: { premium: boolean }) {
  const upgrade = usePremiumUpgrade();
  const color = usePreviewHighlight();
  const [open, setOpen] = useState(false);
  const root = useRef<HTMLDivElement>(null);
  const trigger = useRef<HTMLButtonElement>(null);
  const id = useId();
  const isUpgradeTarget = (target: EventTarget | null) =>
    target instanceof Element &&
    target
      .closest("[data-preview-highlight-upgrade]")
      ?.getAttribute("data-preview-highlight-upgrade") === id;
  const close = () => {
    setOpen(false);
    trigger.current?.focus({ preventScroll: true });
  };
  useEffect(() => {
    if (!open) return;
    root.current
      ?.querySelector<HTMLButtonElement>('[aria-checked="true"]')
      ?.focus({ preventScroll: true });
    const outside = (event: PointerEvent) => {
      if (
        !root.current?.contains(event.target as Node) &&
        !(
          event.target instanceof Element &&
          event.target
            .closest("[data-preview-highlight-upgrade]")
            ?.getAttribute("data-preview-highlight-upgrade") === id
        )
      )
        setOpen(false);
    };
    document.addEventListener("pointerdown", outside);
    return () => document.removeEventListener("pointerdown", outside);
  }, [open, id]);
  return (
    <div
      ref={root}
      className="preview-highlight-picker relative flex-none"
      onBlur={(event) => {
        if (
          !event.currentTarget.contains(event.relatedTarget as Node) &&
          !isUpgradeTarget(event.relatedTarget)
        )
          setOpen(false);
      }}
      onKeyDown=[REDACTED_SECRET]
        if (event.key === "Escape" && open) {
          // Let the tooltip dismiss first, keeping the palette available.
          if (
            document.querySelector(`[data-preview-highlight-upgrade="${id}"]`)
          )
            return;
          event.preventDefault();
          event.stopPropagation();
          close();
          return;
        }
        if (isUpgradeTarget(event.target)) return;
        if (
          ![
            "ArrowLeft",
            "ArrowRight",
            "ArrowUp",
            "ArrowDown",
            "Home",
            "End",
          ].includes(event.key)
        )
          return;
        event.preventDefault();
        if (!open) {
          setOpen(true);
          return;
        }
        const items = Array.from(
          root.current?.querySelectorAll<HTMLButtonElement>(
            '[role="menuitemradio"]',
          ) ?? [],
        );
        const index = items.indexOf(
          document.activeElement as HTMLButtonElement,
        );
        const offset =
          (
            {
              ArrowLeft: -1,
              ArrowRight: 1,
              ArrowUp: -5,
              ArrowDown: 5,
            } as Record<string, number>
          )[event.key] ?? 0;
        items[
          event.key === "Home"
            ? 0
            : event.key === "End"
              ? 9
              : (index + offset + 10) % 10
        ]?.focus();
      }}
    >
      <button
        ref={trigger}
        type="button"
        className="preview-highlight-trigger grid place-items-center w-11 h-11 [border:1px_solid_var(--control-border,_var(--border))] rounded-[10px] [background:var(--card)] cursor-pointer"
        aria-label="Highlight color"
        title={`Highlight color: ${color}`}
        aria-haspopup="menu"
        aria-expanded={open}
        aria-controls={open ? id : undefined}
        onClick={() => (open ? close() : setOpen(true))}
      >
        <span
          className="preview-highlight-swatch w-5 h-5 rounded-[50%] [background:var(--preview-highlight-swatch)]"
          data-preview-highlight={color}
          aria-hidden="true"
        />
      </button>
      {open && (
        <div
          id={id}
          role="menu"
          aria-label="Highlight color"
          className="preview-highlight-menu absolute right-0 [top:calc(100%_+_8px)] z-[50] grid grid-cols-[repeat(5,_36px)] gap-2 w-max p-3 rounded-[14px] [background:var(--card)] [border:1px_solid_var(--control-border,_var(--border))] shadow-[var(--shadow)]"
        >
          {highlightColors.map((name) => {
            const value = name.toLowerCase() as HighlightColor;
            const locked = !premium && value !== "cyan";
            const swatch = (
              <button
                key={value}
                type="button"
                role="menuitemradio"
                aria-label={locked ? `${name} — Premium required` : name}
                title={locked ? undefined : name}
                aria-checked={color === value}
                tabIndex={color === value ? 0 : -1}
                data-preview-highlight={value}
                onClick={() => {
                  if (locked) {
                    upgrade({
                      feature: "highlights",
                      trigger: trigger.current,
                    });
                    setOpen(false);
                    return;
                  }
                  if (premium) choose(value);
                  close();
                }}
              >
                {locked ? (
                  <Crown
                    className="premium-icon"
                    size={14}
                    aria-hidden="true"
                  />
                ) : color === value ? (
                  <Check size={18} aria-hidden="true" />
                ) : null}
              </button>
            );
            return locked ? (
              <Tooltip
                key={value}
                interactive
                placement="top"
                content={
                  <div
                    className="preview-highlight-upgrade"
                    data-preview-highlight-upgrade={id}
                  >
                    <strong>Custom preview highlight colors</strong>
                    <p>
                      Choose from 10 colors to highlight names, companies, and
                      job roles in your email previews. Free includes Cyan.
                    </p>
                    <Link
                      href="/usage"
                      className="relative isolate inline-block overflow-hidden align-middle"
                    >
                      Upgrade to Premium
                    </Link>
                  </div>
                }
              >
                {swatch}
              </Tooltip>
            ) : (
              swatch
            );
          })}
        </div>
      )}
    </div>
  );
}
